#include "AccountSchemaV1.h"
#include <iostream>
using namespace signal_mpc::recovery;
int main(){std::vector<SectionCapacity> caps;for(unsigned t=1;t<=4;++t)caps.push_back({AccountSection(t),0,8});for(unsigned c=0;c<2;++c)for(unsigned t=10;t<=16;++t)caps.push_back({AccountSection(t),c,8*(1+c)});AccountSchemaV1 schema(2,caps);std::vector<QuarantinedEvaluations> parts;size_t total=0;for(auto& x:caps){SecretBytes b(x.bits*16);for(size_t i=0;i<b.size();++i)b.data()[i]=(total+i)%251;total+=b.size();parts.emplace_back(std::move(b));}auto packed=schema.pack(std::move(parts));require(packed.bit_count()==schema.bits(),"pack count");auto split=schema.unpack(std::move(packed));size_t offset=0;for(auto& q:split){for(size_t i=0;i<q.local_bytes().size();++i)require(q.local_bytes().data()[i]==(offset+i)%251,"share codec changed evaluation");offset+=q.local_bytes().size();}unsigned checks=1;auto reject=[&](auto f){bool rejected=false;try{f();}catch(const std::runtime_error&){rejected=true;}require(rejected,"schema accepted malformed input");++checks;};reject([&]{auto c=caps;c.pop_back();AccountSchemaV1 x(2,c);});reject([&]{auto c=caps;c[5].section=AccountSection::Credentials;AccountSchemaV1 x(2,c);});reject([&]{auto c=caps;c[0].bits=7;AccountSchemaV1 x(2,c);});reject([&]{auto c=caps;c[0].bits=1024*1024;AccountSchemaV1 x(2,c);});reject([&]{schema.unpack(QuarantinedEvaluations(SecretBytes(16)));});reject([&]{schema.pack({});});auto c=caps;c[0].bits+=8;require(AccountSchemaV1(2,c).digest()!=schema.digest(),"schema digest omitted capacity");++checks;std::cout<<checks<<" account schema checks passed\n";}
